__NUXT_JSONP__("/inclusion/noticias/unidas_busca_garantizar_que_la_reforma_de_plataformas_digitales_no_deje_atras_a_las_mujeres", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H){return {data:[{post:{slug:"unidas_busca_garantizar_que_la_reforma_de_plataformas_digitales_no_deje_atras_a_las_mujeres",title:"UNIDAS busca garantizar que la reforma de plataformas digitales no deje atrás a las mujeres",date:"2026-01-29T21:38:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F9becb0f0-c9c0-4716-85f8-b1c25957d984\u002F","img-alt":"Unidas",autor:"Mundo Ejecutivo",link:"https:\u002F\u002Fwww.mundoejecutivo.com.mx\u002Funcategorized\u002Funidas-busca-garantizar-que-la-reforma-de-plataformas-digitales-no-deje-atras-a-las-mujeres\u002F",category:"inclusion",extracto:"El acceso a la seguridad social para personas trabajadoras de plataformas digitales está condicionado a alcanzar un ingreso mensual mínimo equivalente al salario mínimo de la Ciudad de México que actualmente equivale a 9 mil 558 pesos.",toc:[{id:p,depth:q,text:r},{id:s,depth:l,text:t},{id:u,depth:l,text:v},{id:w,depth:l,text:x},{id:y,depth:l,text:z},{id:A,depth:l,text:B},{id:C,depth:q,text:D}],body:{type:"root",children:[{type:b,tag:e,props:{},children:[{type:a,value:"La "},{type:b,tag:d,props:{},children:[{type:a,value:"red de mujeres UNIDAS"}]},{type:a,value:" que busca promover el trabajo justo en México, fomentando la organización colectiva de mujeres trabajadoras en sectores informales y precarizados; presentó un nuevo informe sobre las principales "},{type:b,tag:d,props:{},children:[{type:a,value:"barreras estructurales"}]},{type:a,value:" que enfrentan las "},{type:b,tag:d,props:{},children:[{type:a,value:"mujeres trabajadoras de plataformas digitales"}]},{type:a,value:" para acceder a condiciones laborales justas y ejercer plenamente sus derechos."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"El informe ‘Conectadas al cambio: por un trabajo justo para las mujeres en plataformas digitales’, refiere que si bien, la "},{type:b,tag:d,props:{},children:[{type:a,value:"reforma a la Ley Federal del Trabajo en materia de plataformas digitales"}]},{type:a,value:" representa un paso fundamental hacia la formalización del trabajo; "},{type:b,tag:d,props:{},children:[{type:a,value:"no garantiza derechos clave para las mujeres"}]},{type:a,value:", especialmente en materia de "},{type:b,tag:d,props:{},children:[{type:a,value:"seguridad social, maternidad, atención a la violencia y trabajo de cuidados"}]},{type:a,value:o}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Asimismo, señala que los resultados de la implementación de dicha reforma, han evidenciado la necesidad de incluir medidas adicionales para "},{type:b,tag:d,props:{},children:[{type:a,value:"eliminar las barreras estructurales"}]},{type:a,value:" que afectan de forma desproporcionada a las mujeres."}]},{type:a,value:c},{type:b,tag:E,props:{id:p},children:[{type:b,tag:f,props:{ariaHidden:g,href:"#barreras-para-el-acceso-a-la-seguridad-social",tabIndex:h},children:[{type:b,tag:i,props:{className:[j,k]},children:[]}]},{type:a,value:r}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:F},{type:b,tag:d,props:{},children:[{type:a,value:"acceso a la seguridad social"}]},{type:a,value:" para personas trabajadoras de plataformas digitales está condicionado a alcanzar un ingreso mensual mínimo equivalente al salario mínimo de la Ciudad de México que actualmente equivale a 9 mil 558 pesos."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"No obstante, el llamado “"},{type:b,tag:d,props:{},children:[{type:a,value:"factor máximo de exclusión"}]},{type:a,value:"”, un descuento aplicado por las plataformas antes de calcular el "},{type:b,tag:d,props:{},children:[{type:a,value:"ingreso neto"}]},{type:a,value:" eleva el umbral requerido, obligando a ampliar e intensificar la jornada para alcanzar el ingreso."}]},{type:a,value:c},{type:b,tag:m,props:{id:s},children:[{type:b,tag:f,props:{ariaHidden:g,href:"#trabajo-de-cuidados",tabIndex:h},children:[{type:b,tag:i,props:{className:[j,k]},children:[]}]},{type:a,value:t}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Además, la carga de cuidados que recae mayormente en las mujeres, "},{type:b,tag:d,props:{},children:[{type:a,value:"obstaculiza la ampliación de la jornada"}]},{type:a,value:G},{type:b,tag:d,props:{},children:[{type:a,value:"laboral"}]},{type:a,value:" o las orilla a trabajar en horarios y rutas de mayor riesgo."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"De acuerdo con el documento, en el último mes de la prueba piloto, 2 de cada 10 personas inscritas (206 mil 512) lograron superar el umbral de ingresos requerido para "},{type:b,tag:d,props:{},children:[{type:a,value:"acceder a la seguridad social"}]},{type:a,value:o}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Aunque los datos oficiales carecen de desagregación por género, se prevé una marcada "},{type:b,tag:d,props:{},children:[{type:a,value:"subrepresentación femenina"}]},{type:a,value:" en este grupo, consecuencia de las barreras estructurales que dificultan alcanzar dichas metas económicas."}]},{type:a,value:c},{type:b,tag:m,props:{id:u},children:[{type:b,tag:f,props:{ariaHidden:g,href:"#violencia-de-g%C3%A9nero",tabIndex:h},children:[{type:b,tag:i,props:{className:[j,k]},children:[]}]},{type:a,value:v}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Una encuesta aplicada por UNIDAS a 77 trabajadoras de conducción en automóvil y reparto en motocicleta de colectivas de Chihuahua, Jalisco y el Estado de México; revela que siete de cada diez trabajadoras, es decir el 69.7% han sufrido "},{type:b,tag:d,props:{},children:[{type:a,value:"acoso o violencia por parte de usuarios"}]},{type:a,value:o}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Las formas más frecuentes son acoso verbal (77.4%), insinuaciones sexuales (62.3%), contacto físico no deseado (47.2%) e insultos por razón de género (54.7%)."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Aunque la ley obliga a las plataformas a contar con "},{type:b,tag:d,props:{},children:[{type:a,value:"mecanismos de prevención y atención"}]},{type:a,value:G},{type:b,tag:d,props:{},children:[{type:a,value:"de la violencia"}]},{type:a,value:", en la práctica las denuncias reciben respuestas automatizadas o recomendaciones de cancelar el servicio, lo que expone a las víctimas a sanciones algorítmicas y pérdida de ingresos."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Si bien ocho de cada diez contratos de las empresas analizadas por el informe mencionan canales de reporte, ninguna empresa cuenta con protocolos públicos claros que establezcan plazos de respuesta, confidencialidad y medidas de protección, conforme a estándares básicos de derechos laborales."}]},{type:a,value:c},{type:b,tag:m,props:{id:w},children:[{type:b,tag:f,props:{ariaHidden:g,href:"#maternidad-penalizada",tabIndex:h},children:[{type:b,tag:i,props:{className:[j,k]},children:[]}]},{type:a,value:x}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"A pesar de que la afiliación al Instituto Mexicano del Seguro Social (IMSS) reconoce el "},{type:b,tag:d,props:{},children:[{type:a,value:"derecho a la protección a la maternidad"}]},{type:a,value:", el diseño del programa lo vuelve inaccesible."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Para conservar la afiliación, "},{type:b,tag:d,props:{},children:[{type:a,value:"las trabajadoras deben mantenerse activas y generar ingresos mínimos"}]},{type:a,value:", pero el embarazo avanzado y el posparto implican inactividad."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"La norma establece que 30 días consecutivos sin actividad terminan automáticamente la relación laboral, lo que provoca la pérdida de afiliación, aportaciones y servicios como guarderías, penalizando la maternidad y contradiciendo el mandato legal de perspectiva de género."}]},{type:a,value:c},{type:b,tag:m,props:{id:y},children:[{type:b,tag:f,props:{ariaHidden:g,href:"#algoritmos-sin-transparencia-ni-enfoque-de-g%C3%A9nero",tabIndex:h},children:[{type:b,tag:i,props:{className:[j,k]},children:[]}]},{type:a,value:z}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Por otra parte señala, que la gestión algorítmica es central en la relación laboral, pues asigna tareas, evalúa desempeño y aplica sanciones."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Aunque la reforma establece que estas decisiones deben ser transparentes y no discriminatorias, las trabajadoras reportan opacidad y castigos por rechazar viajes inseguros, desconectarse para atender tareas de cuidado o denunciar conductas inapropiadas."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:F},{type:b,tag:d,props:{},children:[{type:a,value:"50.6%"}]},{type:a,value:" de las personas encuestadas señaló que las empresas no han explicado cómo operan los algoritmos. Durante la implementación del periodo piloto de la reforma en materia de plataformas digitales, el "},{type:b,tag:d,props:{},children:[{type:a,value:"18.5% fue bloqueada temporalmente"}]},{type:a,value:" y menos de la mitad logró recuperar su cuenta. Para el 74%, este trabajo es su única fuente de ingresos."}]},{type:a,value:c},{type:b,tag:m,props:{id:A},children:[{type:b,tag:f,props:{ariaHidden:g,href:"#la-flexibilidad-no-aplica-para-las-mujeres",tabIndex:h},children:[{type:b,tag:i,props:{className:[j,k]},children:[]}]},{type:a,value:B}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"La promesa de flexibilidad contrasta con la realidad de las trabajadoras, muchas de las cuales deben permanecer "},{type:b,tag:d,props:{},children:[{type:a,value:"conectadas entre 10 y 12 horas diaria"}]},{type:a,value:"s para alcanzar ingresos mínimos."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"El 85.5% de las encuestadas son madres y, de aquellas con hijas\u002Fos de hasta 4 años, el 84.6% reporta no tener acceso a guarderías, principalmente por costos elevados, horarios incompatibles y falta de información."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Para alcanzar el ingreso mínimo que permite acceder, por ejemplo, al servicio de guarderías del IMSS, las trabajadoras deben laborar en los periodos más rentables —tardes, noches y fines de semana—, precisamente cuando las estancias infantiles no operan, ya que funcionan únicamente en horarios de oficina."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Este obstáculo hace "},{type:b,tag:d,props:{},children:[{type:a,value:"imposible para muchas mujeres trabajar en los horarios de mayor rentabilidad"}]},{type:a,value:" debido al trabajo de cuidados. Así, las mujeres trabajadoras ven en la práctica limitada su autonomía económica y su acceso efectivo a la seguridad social."}]},{type:a,value:c},{type:b,tag:E,props:{id:C},children:[{type:b,tag:f,props:{ariaHidden:g,href:"#recomendaciones-de-pol%C3%ADtica-p%C3%BAblica",tabIndex:h},children:[{type:b,tag:i,props:{className:[j,k]},children:[]}]},{type:a,value:D}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Ante este panorama, UNIDAS presentó "},{type:b,tag:d,props:{},children:[{type:a,value:"recomendaciones"}]},{type:a,value:" dirigidas a la Secretaría del Trabajo y Previsión Social (STPS), el IMSS, y las empresas de plataformas, entre ellas:"}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:"Establecer un “factor de exclusión” diferenciado para mujeres, basado en la brecha de ingresos real, como una medida afirmativa para “emparejar el piso” de acceso a la seguridad social."}]},{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:"Armonizar los criterios del IMSS, la LFT y los contratos de las plataformas para garantizar que la licencia de maternidad se reconozca como un periodo de incapacidad protegido, asegurando la continuidad de la atención médica y las prestaciones."}]},{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:"Diseñar, implementar y monitorear protocolos obligatorios contra la violencia y el acoso a partir de la realidad de las trabajadoras, integrando las mejores prácticas de autocuidado que ellas ya han validado y que las plataformas deben institucionalizar y mejorar."}]},{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:"Garantizar la transparencia y revisión humana en la gestión algorítmica y revisar el sesgo de género para no penalizar el rechazo de viajes por seguridad."}]},{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:"La reforma laboral, concluye el informe, debe cumplir su promesa: transformar la economía digital en un espacio de trabajo justo, libre de violencia y con igualdad de oportunidades para todas las personas."}]},{type:a,value:c}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Funidas_busca_garantizar_que_la_reforma_de_plataformas_digitales_no_deje_atras_a_las_mujeres",extension:".md",createdAt:H,updatedAt:H}}],fetch:{},mutations:[]}}("text","element","\n","strong","p","a","true",-1,"span","icon","icon-link",3,"h3","li",".","barreras-para-el-acceso-a-la-seguridad-social",2,"Barreras para el acceso a la seguridad social","trabajo-de-cuidados","Trabajo de cuidados","violencia-de-género","Violencia de género","maternidad-penalizada","Maternidad penalizada","algoritmos-sin-transparencia-ni-enfoque-de-género","Algoritmos sin transparencia ni enfoque de género","la-flexibilidad-no-aplica-para-las-mujeres","La “flexibilidad” no aplica para las mujeres","recomendaciones-de-política-pública","Recomendaciones de política pública","h2","El "," ","2026-07-19T00:56:17.265Z")));